-- ==============================================================
-- 連鎖門市月報：完整版（救援用）
-- 注意：這份會刪掉現有的七張資料表，你手寫的表和資料都會被取代
-- 只有卡關、或想把資料恢復成第一季的初始狀態時才執行
-- ==============================================================
BEGIN;

DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS stores;
DROP TABLE IF EXISTS raw_sales;

CREATE TABLE stores (
    store_id SERIAL PRIMARY KEY,
    name     VARCHAR(30) NOT NULL UNIQUE,
    region   VARCHAR(10) NOT NULL CHECK (region IN ('北部', '中部', '南部', '東部'))
);

CREATE TABLE staff (
    staff_id SERIAL PRIMARY KEY,
    name     VARCHAR(20) NOT NULL,
    store_id INT NOT NULL REFERENCES stores(store_id),
    UNIQUE (name, store_id)
);

CREATE TABLE products (
    product_id SERIAL PRIMARY KEY,
    name       VARCHAR(50) NOT NULL UNIQUE,
    category   VARCHAR(20) NOT NULL,
    price      INT NOT NULL CHECK (price >= 0)
);

CREATE TABLE customers (
    customer_id SERIAL PRIMARY KEY,
    name        VARCHAR(20) NOT NULL,
    phone       VARCHAR(20) NOT NULL UNIQUE
);

CREATE TABLE orders (
    order_id       VARCHAR(20) PRIMARY KEY,
    order_date     DATE NOT NULL,
    order_time     TIME NOT NULL,
    store_id       INT NOT NULL REFERENCES stores(store_id),
    staff_id       INT NOT NULL REFERENCES staff(staff_id),
    customer_id    INT REFERENCES customers(customer_id),
    payment_method VARCHAR(20) NOT NULL CHECK (payment_method IN ('現金', '信用卡', 'LINE Pay', '街口支付')),
    status         VARCHAR(10) NOT NULL CHECK (status IN ('已完成', '已退款', '已取消'))
);

CREATE TABLE order_items (
    order_id   VARCHAR(20) NOT NULL REFERENCES orders(order_id),
    product_id INT NOT NULL REFERENCES products(product_id),
    quantity   INT NOT NULL CHECK (quantity > 0),
    unit_price INT NOT NULL CHECK (unit_price >= 0),
    PRIMARY KEY (order_id, product_id)
);

CREATE TABLE raw_sales (
    銷售單號 TEXT,
    銷售日期 TEXT,
    時間 TEXT,
    門市名稱 TEXT,
    區域 TEXT,
    經手店員 TEXT,
    會員姓名 TEXT,
    會員電話 TEXT,
    商品分類 TEXT,
    商品名稱 TEXT,
    單價 TEXT,
    數量 TEXT,
    小計 TEXT,
    付款方式 TEXT,
    狀態 TEXT
);


-- 1. 門市
SELECT DISTINCT 門市名稱, 區域
FROM raw_sales
ON CONFLICT (name) DO NOTHING;

-- 2. 店員（同一家店不會重複）
SELECT DISTINCT r.經手店員, s.store_id
FROM raw_sales r
JOIN stores s ON r.門市名稱 = s.name
ON CONFLICT (name, store_id) DO NOTHING;

-- 3. 商品
SELECT DISTINCT 商品名稱, 商品分類, 單價::INT
FROM raw_sales
ON CONFLICT (name) DO NOTHING;

-- 4. 會員（用電話辨識，散客沒有電話，不寫入）
SELECT DISTINCT 會員姓名, 會員電話
FROM raw_sales
WHERE NULLIF(會員電話, '') IS NOT NULL
ON CONFLICT (phone) DO NOTHING;

-- 5. 訂單（散客的 customer_id 是 NULL，所以用 LEFT JOIN）
SELECT DISTINCT r.銷售單號, r.銷售日期::DATE, r.時間::TIME, s.store_id, st.staff_id, c.customer_id, r.付款方式, r.狀態
FROM raw_sales r
JOIN stores s ON r.門市名稱 = s.name
JOIN staff st ON r.經手店員 = st.name AND st.store_id = s.store_id
LEFT JOIN customers c ON NULLIF(r.會員電話, '') = c.phone
ON CONFLICT (order_id) DO NOTHING;

-- 6. 訂單明細
SELECT r.銷售單號, p.product_id, r.數量::INT, r.單價::INT
FROM raw_sales r
JOIN products p ON r.商品名稱 = p.name
ON CONFLICT (order_id, product_id) DO NOTHING;

COMMIT;
